Here is the commit message:
EDAC/versalnet: Fix device name memory leak

The device name allocated via kzalloc() in init_one_mc() is assigned to
dev->init_name but never freed on the normal removal path.  device_register()
copies init_name and then sets dev->init_name to NULL, so the name pointer
becomes unreachable from the device. Thus leaking memory.

Use a stack-local char array instead of using kzalloc() for name.

Fixes: d5fe2fec6c40 ("EDAC: Add a driver for the AMD Versal NET DDR controller")
Signed-off-by: Prasanna Kumar T S M <ptsm@linux.microsoft.com>
Signed-off-by: Borislav Petkov (AMD) <bp@alien8.de>
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20260401111856.2342975-1-ptsm@linux.microsoft.com

Here is the root cause:
The bug is a memory leak in the `init_one_mc()` function. A device name buffer is allocated with `kzalloc()` and assigned to `dev->init_name`. However, `device_register()` copies the string and sets `dev->init_name` to NULL, making the original dynamically allocated pointer unreachable. Since there is no corresponding `kfree()` on the normal removal path or after registration, the allocated memory leaks.

Here is the patch:

 static int init_one_mc(struct mc_priv *priv, struct platform_device *pdev, int i)
 {
 	u32 num_chans, rank, dwidth, config;
 	struct edac_mc_layer layers[2];
 	struct mem_ctl_info *mci;
+	char name[MC_NAME_LEN];
 	struct device *dev;
 	enum dev_type dt;
-	char *name;
 	int rc;

 	config = priv->adec[CONF + i * ADEC_NUM];
 	num_chans = FIELD_GET(MC5_NUM_CHANS_MASK, config);
 	rank = 1 << FIELD_GET(MC5_RANK_MASK, config);
 	dwidth = FIELD_GET(MC5_BUS_WIDTH_MASK, config);

 	switch (dwidth) {
 	case XDDR5_BUS_WIDTH_16:
 		dt = DEV_X16;
 		break;
 	case XDDR5_BUS_WIDTH_32:
 		dt = DEV_X32;
 		break;
 	case XDDR5_BUS_WIDTH_64:
 		dt = DEV_X64;
 		break;
 	default:
 		dt = DEV_UNKNOWN;
 	}

 	if (dt == DEV_UNKNOWN)
 		return 0;

 	/* Find the first enabled device and register that one. */
 	layers[0].type = EDAC_MC_LAYER_CHIP_SELECT;
 	layers[0].size = rank;
 	layers[0].is_virt_csrow = true;
 	layers[1].type = EDAC_MC_LAYER_CHANNEL;
 	layers[1].size = num_chans;
 	layers[1].is_virt_csrow = false;

 	rc = -ENOMEM;
-	name = kzalloc(MC_NAME_LEN, GFP_KERNEL);
-	if (!name)
-		return rc;
-
 	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
 	if (!dev)
-		goto err_name_free;
+		return rc;

 	mci = edac_mc_alloc(i, ARRAY_SIZE(layers), layers, sizeof(struct mc_priv));
 	if (!mci) {
 		edac_printk(KERN_ERR, EDAC_MC, "Failed memory allocation for MC%d\n", i);
 		goto err_dev_free;
 	}

 	sprintf(name, "versal-net-ddrmc5-edac-%d", i);

 	dev->init_name = name;
 	dev->release = versal_edac_release;

 	rc = device_register(dev);
 	if (rc)
 		goto err_mc_free;

 	mci->pdev = dev;
 	mc_init(mci, dev);

 	rc = edac_mc_add_mc(mci);
 	if (rc) {
 		edac_printk(KERN_ERR, EDAC_MC, "Failed to register MC%d with EDAC core\n", i);
 		goto err_unreg;
 	}

 	priv->mci[i] = mci;
 	priv->dwidth = dt;

 	platform_set_drvdata(pdev, priv);

 	return 0;

 err_unreg:
 	device_unregister(mci->pdev);
 err_mc_free:
 	edac_mc_free(mci);
 err_dev_free:
 	kfree(dev);
-err_name_free:
-	kfree(name);

 	return rc;
 }



